using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Newtonsoft.Json.Linq;
public static class LegacyShading {public static string Main(){var root=Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"../../tmp/Existing_VARCO_Repair_20261103"));var cfg=JArray.Parse(File.ReadAllText(Path.Combine(root,"repair_export_manifest.json")));Directory.CreateDirectory(Path.Combine(root,"MaterialBackup"));foreach(var a in cfg){var go=AssetDatabase.LoadAssetAtPath<GameObject>((string)a["prefabPath"]);foreach(var mat in go.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Distinct()){string p=AssetDatabase.GetAssetPath(mat);string backup=Path.Combine(root,"MaterialBackup",(string)a["name"]+"_"+Path.GetFileName(p));if(!File.Exists(backup))File.Copy(p,backup);if(mat.HasProperty("_BumpScale"))mat.SetFloat("_BumpScale",.35f);EditorUtility.SetDirty(mat);}}AssetDatabase.SaveAssets();return "8 original material normal strengths reduced to .35; backups saved";}}
